// Fazıl Irak, 26.10.2026: 528 Hz seçimi için genişletilen A4 aralığı.
// Fare hızını Hz/piksel cinsinden korumak için panel de aynı sabitleri kullanır.
pub const GLOBAL_TUNING_MIN:f32=400.0;
pub const GLOBAL_TUNING_MAX:f32=540.0;
pub const GLOBAL_TUNING_SPAN:f32=GLOBAL_TUNING_MAX-GLOBAL_TUNING_MIN;

// Keep each constructor's temporary storage out of the 1840-field default frame.
// Instance setup runs off the audio thread; sample processing only reads these objects.
#[inline(never)]
fn boxed_float_param(name:&'static str,default:f32,min:f32,max:f32,step:f32)->Box<FloatParam> {
    Box::new(FloatParam::new(name,default,FloatRange::Linear {min,max}).with_step_size(step))
}

// All controls use stable IDs and are saved/automated by the host. Switches and
// selectors are stepped floats so the small editor can share one gesture path.
macro_rules! parameters {
    ($( $id:ident: $key:literal => ($name:literal, $min:expr, $max:expr, $default:expr, $step:expr) ),* $(,)?) => {
        #[derive(Params, Debug)]
        pub struct ModelFParams {
            #[persist = "preset_name"]
            pub preset_name: Arc<RwLock<String>>,
            $(#[id = $key] pub $id: Box<FloatParam>,)*
        }
        impl Default for ModelFParams {
            fn default() -> Self {
                Self {
                    preset_name: Arc::new(RwLock::new("Init — Model F".into())),
                    $($id: boxed_float_param($name,$default,$min,$max,$step),)*
                }
            }
        }
        impl ModelFParams {
            pub fn list(&self) -> Vec<(&'static str, &FloatParam)> { vec![$((stringify!($id), &self.$id)),*] }
            pub fn get(&self, id: &str) -> Option<&FloatParam> { match id { $(stringify!($id) => Some(&self.$id),)* _ => None } }
        }
    }
}
